scwin.setData = function(ds, col_cnt, row_cnt) {
    var objDate = new Date();
    var nStartTime = objDate.getTime(); //Milliseconds

    for (var i = 0; i < row_cnt; i++) {
        var nRow = ds.insertRow();
        for (var j = 0; j < col_cnt; j++) {
            var sCol = "Col" + j;
            ds.setCellData(nRow, sCol, scwin._setData);
        }
    }
    var endTime = scwin._endTime(nStartTime);
    var sctObj = eval("stc_" + col_cnt + "_" + row_cnt);
    sctObj.setValue(endTime);
};
scwin.setData2 = function(ds, col_cnt, row_cnt) {
    var objDate = new Date();
    var nStartTime = objDate.getTime(); //Milliseconds

    for (var i = 0; i < row_cnt; i++) {
        var nRow = ds.insertRow();
        for (var j = 0; j < col_cnt; j++) {
            var sCol = "Col" + j;
            ds.setCellData(nRow, sCol, scwin._setData);
        }
    }
    var endTime = scwin._endTime(nStartTime);
    var sctObj = eval("tc_" + col_cnt + "_" + row_cnt);
    sctObj.setValue(endTime);
};
scwin._endTime = function(nStartTime) {
    var objDate = new Date();
    var nEndTime = objDate.getTime(); //Milliseconds
    var nElapseSec = (nEndTime - nStartTime) / 1000;
    return nElapseSec;
};
